"use client";

import type { ReactNode } from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";

export type NotificationPosition = "top" | "top-right";
export type NotificationStyle = "ios" | "macos";

export interface NotificationItem {
  /** App icon node. Falls back to a rounded tile with the app initial. */
  icon?: ReactNode;
  appName: string;
  title: string;
  body: string;
  /** Timestamp label rendered on the right. Defaults to "now". */
  time?: string;
  /** Frame at which the banner slides in. */
  startFrame: number;
  /** Frame at which the banner slides back out. Omit to keep it on screen. */
  dismissFrame?: number;
}

export interface NotificationPopupProps {
  notifications?: NotificationItem[];
  /** "top" centers the banners (iOS); "top-right" pins them to the corner (macOS). */
  position?: NotificationPosition;
  /** Banner chrome: iOS uppercase app header or macOS bold app line. */
  style?: NotificationStyle;
  /** When true, later banners push earlier ones down into a card stack. */
  stackable?: boolean;
  /** Banner width in px. Defaults to 420 (ios) / 380 (macos). */
  width?: number;
  /** Distance from the top edge in px. */
  topOffset?: number;
  /** Vertical offset per stack level in px. */
  stackOffset?: number;
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/** Frames a dismissing banner takes to slide out. */
export const EXIT_DURATION = 12;

export interface NotificationTiming {
  startFrame: number;
  dismissFrame?: number;
}

/**
 * 0 → 1 progress of a banner's exit. 0 before `dismissFrame`, 1 once the
 * banner has fully left, linear in between. Banners without a
 * `dismissFrame` never exit.
 */
export function exitProgress(
  frame: number,
  dismissFrame: number | undefined,
  exitDuration: number = EXIT_DURATION,
): number {
  if (dismissFrame === undefined || exitDuration <= 0) return 0;
  if (frame <= dismissFrame) return 0;
  if (frame >= dismissFrame + exitDuration) return 1;
  return (frame - dismissFrame) / exitDuration;
}

/**
 * How many banners are currently stacked IN FRONT of `items[index]`,
 * as a smooth fractional value: each later banner contributes its enter
 * progress times how un-dismissed it still is. Multiplied by the per-level
 * offset this yields the animated "push earlier ones down" translation.
 *
 * `enter` maps a banner-local frame (frame - startFrame) to 0..1 progress;
 * ties on `startFrame` are broken by array order (later index = in front).
 */
export function stackDepth(
  frame: number,
  index: number,
  items: readonly NotificationTiming[],
  enter: (localFrame: number) => number,
  exitDuration: number = EXIT_DURATION,
): number {
  const self = items[index];
  if (!self) return 0;
  let depth = 0;
  for (let j = 0; j < items.length; j++) {
    if (j === index) continue;
    const other = items[j];
    const isLater =
      other.startFrame > self.startFrame ||
      (other.startFrame === self.startFrame && j > index);
    if (!isLater) continue;
    depth +=
      enter(frame - other.startFrame) *
      (1 - exitProgress(frame, other.dismissFrame, exitDuration));
  }
  return depth;
}

/** Demo timeline: two Acme banners, the second stacking 40 frames later. */
export const DEMO_NOTIFICATIONS: NotificationItem[] = [
  {
    appName: "Acme",
    title: "Payment received",
    body: "$2,400 from Initech",
    time: "now",
    startFrame: 12,
  },
  {
    appName: "Acme",
    title: "Invoice #1042 viewed",
    body: "Vandelay Industries just opened invoice #1042.",
    time: "now",
    startFrame: 52,
  },
];

function DefaultAppIcon({ appName }: { appName: string }) {
  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        borderRadius: "inherit",
        background: "linear-gradient(180deg, #4A87F4 0%, #266DF0 100%)",
        color: "#FFFFFF",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: 19,
        fontWeight: 600,
        letterSpacing: "-0.01em",
      }}
    >
      {appName.trim().charAt(0).toUpperCase() || "A"}
    </div>
  );
}

export function NotificationPopup({
  notifications = DEMO_NOTIFICATIONS,
  position = "top",
  style = "ios",
  stackable = true,
  width,
  topOffset = 24,
  stackOffset = 8,
  speed = 1,
  className,
}: NotificationPopupProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const bannerWidth = width ?? (style === "macos" ? 380 : 420);

  // High-damping spring: fast, settles clean, no bounce on chrome.
  const enter = (localFrame: number) =>
    localFrame <= 0
      ? 0
      : spring({
          fps,
          frame: localFrame,
          config: { damping: 200, stiffness: 190, mass: 0.8 },
        });

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        pointerEvents: "none",
        fontFamily: FONT_FAMILY,
      }}
    >
      {notifications.map((item, i) => {
        const local = frame - item.startFrame;
        const enterP = enter(local);
        const exitP = exitProgress(frame, item.dismissFrame);
        const depth = stackable
          ? stackDepth(frame, i, notifications, enter)
          : 0;

        // Not started, or fully gone — skip.
        if (local < 0 || exitP >= 1) return null;

        // Non-stackable: the newest banner replaces earlier ones.
        const replaced = stackable
          ? 0
          : Math.min(1, stackDepth(frame, i, notifications, enter));

        const slideIn = (1 - enterP) * -(topOffset + 120);
        const pushDown = stackable ? depth * stackOffset : 0;
        const slideOut = (exitP + replaced) * -36;

        return (
          <div
            key={`${item.appName}-${item.startFrame}-${i}`}
            style={{
              position: "absolute",
              top: topOffset,
              left: 0,
              right: 0,
              display: "flex",
              justifyContent: position === "top-right" ? "flex-end" : "center",
              paddingRight: position === "top-right" ? 24 : 0,
              zIndex: 10 + Math.round(item.startFrame) + i,
            }}
          >
            <div
              style={{
                width: bannerWidth,
                boxSizing: "border-box",
                display: "flex",
                alignItems: "flex-start",
                gap: 12,
                padding: "12px 14px",
                borderRadius: 10,
                backgroundColor: "rgba(255,255,255,0.92)",
                backdropFilter: "blur(24px)",
                WebkitBackdropFilter: "blur(24px)",
                border: "1px solid #E4E7EC",
                boxShadow: "0 12px 32px rgba(16,24,40,0.12)",
                transformOrigin: "50% 0%",
                translate: `0px ${slideIn + pushDown + slideOut}px`,
                scale: String(
                  Math.max(0.88, 1 - depth * 0.03) * (1 - exitP * 0.04),
                ),
                opacity:
                  interpolate(local, [0, 8], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }) *
                  (1 - exitP) *
                  (1 - replaced) *
                  Math.max(0.55, 1 - depth * 0.12),
              }}
            >
              <div
                style={{
                  width: 38,
                  height: 38,
                  flexShrink: 0,
                  borderRadius: 9,
                  overflow: "hidden",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {item.icon ?? <DefaultAppIcon appName={item.appName} />}
              </div>

              <div style={{ flex: 1, minWidth: 0 }}>
                <div
                  style={{
                    display: "flex",
                    alignItems: "baseline",
                    justifyContent: "space-between",
                    gap: 8,
                    marginBottom: 2,
                  }}
                >
                  {style === "macos" ? (
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: 600,
                        letterSpacing: "-0.01em",
                        color: "#101828",
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                      }}
                    >
                      {item.appName}
                    </span>
                  ) : (
                    <span
                      style={{
                        fontSize: 11,
                        fontWeight: 500,
                        textTransform: "uppercase",
                        letterSpacing: "0.04em",
                        color: "#667085",
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                      }}
                    >
                      {item.appName}
                    </span>
                  )}
                  <span
                    style={{
                      fontSize: 12,
                      color: "#667085",
                      flexShrink: 0,
                    }}
                  >
                    {item.time ?? "now"}
                  </span>
                </div>

                <div
                  style={{
                    fontSize: 15,
                    fontWeight: 600,
                    letterSpacing: "-0.01em",
                    lineHeight: 1.35,
                    color: "#101828",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {item.title}
                </div>

                <div
                  style={{
                    fontSize: 14,
                    lineHeight: 1.4,
                    color: "#667085",
                    display: "-webkit-box",
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: "vertical",
                    overflow: "hidden",
                  }}
                >
                  {item.body}
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
